from pathlib import Path
import base64,json
from playwright.sync_api import sync_playwright
ROOT=Path('/workspace/shared/R05-ui-review/storage')
IDS=['puffer','chicken','bubble_fish','electric_sheep','magnet_crab','duck','rabbit','cactus','shell_turtle','crow']
NAMES=['充气球','炸弹母鸡','泡泡鱼','触电羊','磁铁蟹','倒霉鸭','锻造兔','仙人掌','脱壳乌龟','乌鸦']
IMAGES={}
for ident in IDS:
 p=Path('/workspace/balls/assets')/('r02' if ident in ['duck','rabbit'] else 'r04')/'characters'/ident/('default.png' if ident in ['duck','rabbit'] else 'idle.png')
 IMAGES[ident]='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
def sprite(id='bubble_fish',size=160):return f'<img class="sprite" src="{IMAGES[id]}" style="width:{size}px;height:{size}px">'
def pane(content,cls=''):return f'<section class="pane {cls}">{content}</section>'
def heading(k,v):return f'<div class="eyebrow">{k}</div><h2>{v}</h2>'
def stats():
 s='<div class="sectionhead"><b>六维属性</b><span>全部来源</span></div><table><thead><tr><th>属性</th><th>种族基础</th><th>先天</th><th>后天</th><th>最终</th></tr></thead><tbody>'
 for name,val in zip(['生命','攻击','防御','速度','重量','大小'],[34,41,48,12,19,26]):s+=f'<tr><th>{name}</th><td class="muted">待定</td><td><b>{val}</b></td><td>0</td><td class="muted">待定</td></tr>'
 return s+'</tbody></table>'
def traits():return '<div class="sectionhead"><b>特性</b><span>1 / 3</span></div><div class="trait">✦ 特性一 <small>待设计</small></div><div class="hint">其他特性：特性二、特性三 · 待设计</div>'
def skills(compact=False):return '<div class="sectionhead"><b>已拥有技能</b><span>2 / 5</span></div><div class="skills"><div><i>◉</i><b>吸附泡泡</b><strong>+3</strong></div><div><i>✣</i><b>八方泡泡</b><strong>+3</strong></div></div><div class="hint">其他技能：技能三、技能四、技能五 · 待设计</div>'
def identity():return '<div class="eyebrow">已选择</div><h1>泡泡鱼 <em>♀</em></h1><div class="chips"><span>Lv.0</span><details class="individual-picker"><summary>♀ 示例个体　▾</summary><div class="individual-options"><button>♀　Lv.0　当前个体</button><button>♂　Lv.0　另一示例</button><small>选择后查看该个体资料</small></div></details></div>'
def gallery(mode='list'):
 out=''
 entries=[(i,id,sex) for i,id in enumerate(IDS) for sex in (['♀','♂'] if mode=='list' else ['group'])]
 for i,id,sex in entries:
  active=' active' if id=='bubble_fish' and sex!='♂' else ''
  caption=('2 个示例 · ♀ / ♂' if sex=='group' else sex+'  Lv.0 · 示例个体')
  out+=f'<button class="creature {mode}{active}">{sprite(id,72 if mode=="list" else 132)}<span>{NAMES[i]}<small>{caption}</small></span>{"<i>●</i>" if active else ""}</button>'
 return out
