c='<div style="display:grid;grid-template-columns:110px 1fr;gap:22px;padding:28px 34px;height:762px"><div style="display:grid;gap:9px;align-content:start">'+''.join(f'<button class="subaction" style="padding:3px;border:2px solid {"#648d7b" if i==4 else "#c6d0be"};background:{"#d7e9dc" if i==4 else "#f4f4e9"}">{sprite(id,58)+f'<small style="display:block;font-size:12px">{"♀" if i%2==0 else "♂"} Lv.0</small>'}</button>' for i,id in enumerate(['puffer','puffer','chicken','chicken','bubble_fish','bubble_fish','electric_sheep']))+'</div><div style="position:relative;display:grid;grid-template-columns:1fr 1fr;background:#faf6e8;border:3px solid #b1bda7;border-radius:12px;box-shadow:8px 8px 0 #c4cebd"><div style="padding:26px 35px;border-right:2px solid #d4d9c6;background:linear-gradient(90deg,#fbf9ef 90%,#e8e7d6)"><div class="eyebrow">个体图鉴 / 05</div><div style="display:flex;align-items:center;justify-content:space-between">'+identity()+'<span style="font-size:52px;color:#a2b1a0">05</span></div><div class="hero" style="height:220px;margin:16px 0">'+sprite(size=256)+'</div>'+skills()+'</div><div style="padding:32px 35px;background:linear-gradient(90deg,#e9e8d7,#fbf9ef 6%)"><div class="tabrow" style="margin:0 0 22px"><button class="selected">资料</button><button>特性说明</button><button>技能说明</button></div>'+traits()+'<div class="divider"></div>'+stats()+'<div style="display:flex;justify-content:space-between;margin-top:14px"><button class="subaction">‹ 上一只</button><span class="hint">05 / 20+</span><button class="subaction">下一只 ›</button></div></div></div></div>'
d='<div style="padding:22px 34px"><div style="display:flex;justify-content:space-between;align-items:center"><h2 style="margin:0">精灵画廊</h2><div class="chips"><span>‹　滑动切换精灵　›</span><span>05 / 20+</span></div></div><div style="height:260px;display:grid;grid-template-columns:1fr 1fr 1.7fr 1fr 1fr;gap:16px;align-items:center;margin:16px 0 20px">'+''.join('<div class="hero" style="height:'+('255px' if i==2 else '190px')+';'+('border:3px solid #7b9b7f;background:#e7f0df' if i==2 else 'opacity:.72')+';flex-direction:column">'+sprite(id,205 if i==2 else 125)+('<h3>泡泡鱼 ♀ <span style="font-size:16px;color:#788b78">Lv.0</span></h3>' if i==2 else '<div>'+NAMES[IDS.index(id)]+(' ♀' if i in [0,2,4] else ' ♂')+' Lv.0</div>')+'</div>' for i,id in enumerate(['chicken','chicken','bubble_fish','bubble_fish','electric_sheep']))+'</div><div style="display:grid;grid-template-columns:1.35fr 1fr;gap:24px;height:360px">'+pane('<div class="sectionhead"><b>属性抽屉 · 已展开</b><span>收起 ▾</span></div>'+stats(),'attrdrawer')+pane(traits()+'<div class="divider" style="margin:14px 0"></div>'+skills())+'</div></div>'

# Progressive-disclosure candidates: keep A/C full matrix; B/D default summaries.
