CSS += '.individual-options{position:absolute;top:48px;left:0;width:230px;padding:10px;background:#fcfaf2;border:2px solid #789782;border-radius:6px;box-shadow:5px 5px 0 #bdccb6;z-index:8}.individual-options button{display:block;width:100%;text-align:left;padding:12px;background:#edf2e7;margin:4px 0;font-size:16px;min-height:48px}.individual-options small{display:block;padding:7px;font-size:12px}.individual-picker summary{list-style:none;cursor:pointer}.individual-picker{position:relative}.individual-picker{background:#e8efe3;border:1px solid #a7bbaa;border-radius:5px;padding:5px 10px;font-size:15px;min-height:44px}.innate-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.innate-grid>div{display:flex;align-items:center;justify-content:space-between;background:#edf2e7;border:1px solid #c9d5bf;border-radius:6px;padding:12px 14px}.innate-grid small{font-size:16px}.innate-grid b{font-size:25px;color:#486c5e}.detail-modal{position:absolute;left:430px;top:142px;width:1120px;height:675px;z-index:5;padding:30px;background:#fcfaf2;border:3px solid #74927c;border-radius:12px;box-shadow:0 15px 50px #263d3b4d}.detail-modal table{font-size:23px}.detail-modal table th,.detail-modal table td{padding:13px 10px}.detail-modal th:first-child{width:17%}.detail-modal thead{font-size:19px}'
