 data={'id':id,'title':title,'image':'screen.png','difference':diff,'strength':strength,'limit':limit,'detail_images':(['detail.png','individual_selection.png'] if id=='b' else ['detail.png'] if id in DETAILS else []),'status':'横屏布局候选，未接入游戏','canvas':[1600,900],'sample':{'species':'bubble_fish','sex':'female','level':0,'skills':[{'name':'吸附泡泡','rank':3},{'name':'八方泡泡','rank':3}],'innate':[34,41,48,12,19,26],'training':[0]*6,'base':'待定','final':'待定'},'source':'source.html','notes':['搜索/筛选/抽屉/翻页仅候选交互；不是当前游戏已实现API','20个固定示例（10种类×两性）与本机实际孵出个体同仓库；图中为示例种类陈列，未捏造后代']}
